<?php
namespace LibreNMS\Plugins\InterfaceAlertPolicyManager\Http\Controllers;
use Illuminate\Http\Request; use Illuminate\Routing\Controller; use Illuminate\Support\Facades\Artisan; use Illuminate\Support\Facades\DB; use LibreNMS\Plugins\InterfaceAlertPolicyManager\Enums\IncidentState; use LibreNMS\Plugins\InterfaceAlertPolicyManager\Models\Incident; use LibreNMS\Plugins\InterfaceAlertPolicyManager\Services\AuditService;
class IncidentController extends Controller { public function index(Request $r){$q=Incident::with('policy');if($r->filled('state'))$q->where('state',$r->string('state'));if($r->filled('device_id'))$q->where('device_id',$r->integer('device_id'));
        // Urgent-first: active before pending/ack/suppressed/recovered, critical
        // before warning, then oldest first — so a triage screen surfaces what matters.
        $q->orderByRaw("CASE state WHEN 'active' THEN 0 WHEN 'pending' THEN 1 WHEN 'acknowledged' THEN 2 WHEN 'suppressed' THEN 3 ELSE 4 END")
          ->orderByRaw("CASE severity WHEN 'critical' THEN 0 WHEN 'warning' THEN 1 ELSE 2 END")
          ->orderBy('first_seen_at');
        return view('iapm::incidents.index',['incidents'=>$q->paginate(50)->withQueryString()]);} public function show(Incident $incident){return view('iapm::incidents.show',['incident'=>$incident->load(['policy.actions.destination','events','deliveries'])]);} public function acknowledge(Request $r,Incident $incident,AuditService $audit){abort_unless($r->user()->can('acknowledge iapm incidents'),403);abort_if($incident->state===IncidentState::Recovered,409);$before=$incident->toArray();$incident->update(['state'=>IncidentState::Acknowledged,'acknowledged_at'=>now(),'acknowledged_by'=>$r->user()->getAuthIdentifier()]);$incident->events()->create(['event_type'=>'acknowledged','event_message'=>'Incident acknowledged.','actor_user_id'=>$r->user()->getAuthIdentifier()]);$audit->record($r,'acknowledged','incident',$incident,$before,$incident->toArray());return back()->with('status','Incident acknowledged.');} public function unacknowledge(Request $r,Incident $incident,AuditService $audit){abort_unless($r->user()->can('acknowledge iapm incidents'),403);$incident->update(['state'=>IncidentState::Active,'acknowledged_at'=>null,'acknowledged_by'=>null]);$incident->events()->create(['event_type'=>'unacknowledged','event_message'=>'Acknowledgement removed.','actor_user_id'=>$r->user()->getAuthIdentifier()]);$audit->record($r,'unacknowledged','incident',$incident);return back();} public function mute(Request $r,Incident $incident,AuditService $audit){abort_unless($r->user()->can('mute iapm incidents'),403);$d=$r->validate(['muted_until'=>['required','date','after:now']]);$incident->update(['muted_until'=>$d['muted_until']]);$incident->events()->create(['event_type'=>'muted','event_message'=>'Notifications muted until '.$d['muted_until'],'actor_user_id'=>$r->user()->getAuthIdentifier()]);$audit->record($r,'muted','incident',$incident,null,['muted_until'=>$d['muted_until']]);return back();} public function unmute(Request $r,Incident $incident,AuditService $audit){abort_unless($r->user()->can('mute iapm incidents'),403);$incident->update(['muted_until'=>null]);$incident->events()->create(['event_type'=>'unmuted','event_message'=>'Notifications unmuted.','actor_user_id'=>$r->user()->getAuthIdentifier()]);$audit->record($r,'unmuted','incident',$incident);return back();} public function reconcile(Request $r,Incident $incident){abort_unless($r->user()->can('acknowledge iapm incidents'),403);Artisan::call('iapm:reconcile',['--incident'=>$incident->id]);return back()->with('status',trim(Artisan::output()));} public function resend(Request $r,Incident $incident,AuditService $audit){abort_unless($r->user()->can('acknowledge iapm incidents'),403);$d=$r->validate(['action_id'=>['required','integer','exists:iapm_policy_actions,id']]);abort_unless($incident->policy?->actions()->whereKey($d['action_id'])->exists(),422);Artisan::call('iapm:process-actions',['--incident'=>$incident->id,'--action'=>$d['action_id'],'--force'=>true]);$audit->record($r,'resent','incident',$incident,null,['action_id'=>$d['action_id']]);return back()->with('status',trim(Artisan::output()));} }
